INSERT INTO regular_expressions (name, pattern, description, regex101_id) VALUES ('Foreign Language Tag', '\b(?:19|20)\d{2}\b.*\b(?:POLISH|PLDUB|TRUEFRENCH|VFF|VFQ|VFI|VF2|FRENCH|GERMAN|iTALiAN|ITA|SPANISH|CASTELLANO|LATINO|RUSSIAN|RUS|UKRAINIAN|HINDI|TAMIL|TELUGU|PORTUGUESE|BRAZILIAN|CZECH|HUNGARIAN|TURKISH|SWEDISH|DANISH|NORWEGIAN|FINNISH|DUTCH|FLEMISH|NORDIC|JAPANESE|KOREAN|CHINESE|MANDARIN|CANTONESE|THAI|ARABIC|PERSIAN|HEBREW)\b(?![ ._-]*CUT\b)', 'HTB. An explicit audio-language tag after the year, not followed by CUT.', NULL);
